// Set a PIN for the owner dashboard. Keep it different from the staff PIN.
// While it is still CHANGE_ME, every request is rejected.
const OWNER_PIN = 'CHANGE_ME';

const toLatin = s => String(s ?? '')
  .replace(/[٠-٩]/g, d => '٠١٢٣٤٥٦٧٨٩'.indexOf(d))
  .replace(/[۰-۹]/g, d => '۰۱۲۳۴۵۶۷۸۹'.indexOf(d));

function normalizePhone(raw) {
  let d = toLatin(raw).replace(/\D/g, '');
  if (d.startsWith('00')) d = d.slice(2);
  if (d.startsWith('0') && d.length === 11) d = '20' + d.slice(1);
  else if (d.startsWith('1') && d.length === 10) d = '20' + d;
  return /^201[0125]\d{8}$/.test(d) ? d : '';
}

const b = $input.first().json.body ?? {};
const pinOk = OWNER_PIN !== 'CHANGE_ME' && String(b.pin ?? '') === OWNER_PIN;
const rawNumbers = String(b.numbers ?? '');
const pieces = rawNumbers.split(/[\s,;،]+/).map(s => s.trim()).filter(Boolean);
const numbers = new Set();
let ignoredNumbers = 0;

for (const piece of pieces) {
  const normalized = normalizePhone(piece);
  if (normalized) numbers.add(normalized);
  else ignoredNumbers += 1;
}

return [{
  json: {
    pin_ok: pinOk,
    numbers: [...numbers],
    ignoredNumbers,
  },
}];

const req = $('Validate owner input').first().json;
const phoneSet = new Set(req.numbers || []);

const toLatin = s => String(s ?? '')
  .replace(/[٠-٩]/g, d => '٠١٢٣٤٥٦٧٨٩'.indexOf(d))
  .replace(/[۰-۹]/g, d => '۰۱۲۳۴۵۶۷۸۹'.indexOf(d));

function normalizePhone(raw) {
  let d = toLatin(raw).replace(/\D/g, '');
  if (d.startsWith('00')) d = d.slice(2);
  if (d.startsWith('0') && d.length === 11) d = '20' + d.slice(1);
  else if (d.startsWith('1') && d.length === 10) d = '20' + d;
  return /^201[0125]\d{8}$/.test(d) ? d : '';
}

const rows = $input.all()
  .map(item => item.json || {})
  .filter(row => Object.keys(row).length > 0);

const invitedStages = new Set(['followup1_sent', 'visited']);
let registered = 0;
let invited = 0;
let visited = 0;
const matches = [];

for (const row of rows) {
  const stage = String(row.Stage ?? '').trim().toLowerCase();
  registered += 1;
  if (invitedStages.has(stage)) invited += 1;
  if (stage === 'visited') {
    visited += 1;
    const phone = normalizePhone(row['WhatsApp Number']);
    if (phone && phoneSet.has(phone)) {
      matches.push({
        name: row.Name ?? '',
        visitedAt: row.UsedAt ?? '',
      });
    }
  }
}

return [{
  json: {
    status: 'ok',
    registered,
    invited,
    visited,
    matched: matches.length,
    matches,
    ignoredNumbers: req.ignoredNumbers || 0,
  },
}];
